        self._lock = threading.Lock()
    def set(self, key, value, ttl_seconds):
        with self._lock:
            self._store[key] = (value, time.monotonic() + ttl_seconds)
    def get(self, key):
        with self._lock:
            if key not in self._store:
                return None
            value, expires = self._store[key]
