class CircuitBreaker:
    def __init__(self, failure_threshold=5, recovery_timeout=30):
        self.threshold = failure_threshold
        self.timeout = recovery_timeout
        self.failures = 0
        self.state = 'closed'
        self.last_failure = 0
    def call(self, func):
        if self.state == 'open':
            if time.monotonic() - self.last_failure >= self.timeout:
                self.state = 'half_open'
            else:
                raise CircuitBreakerOpen()
        try:
            result = func()
            self.failures = 0
            self.state = 'closed'
            return result
        except Exception:
            self.failures += 1
            self.last_failure = time.monotonic()
            if self.failures >= self.threshold:
                self.state = 'open'
            raise

def validate_schema(data, schema):
    errors = []
    type_map = {'string': str, 'int': int, 'float': (int, float), 'bool': bool, 'list': list, 'dict': dict}
    for field, rules in schema.items():
        value = data.get(field)
        if value is None:
            if rules.get('required'):
                errors.append(f'{field}: required')
            continue
        expected = type_map.get(rules.get('type', ''))
        if expected and not isinstance(value, expected):
            errors.append(f'{field}: wrong type')
            continue
        if 'min' in rules:
            v = len(value) if isinstance(value, (str, list)) else value
            if v < rules['min']:
                errors.append(f'{field}: below min')
        if 'max' in rules:
            v = len(value) if isinstance(value, (str, list)) else value
            if v > rules['max']:
                errors.append(f'{field}: above max')
    return (len(errors) == 0, errors)

