class TaskQueue:
    def __init__(self, num_workers=4):
        self._queue = []
        self._lock = threading.Lock()
        self._cond = threading.Condition(self._lock)
        self._counter = 0
        self._shutdown = False
        self._workers = [threading.Thread(target=self._work, daemon=True) for _ in range(num_workers)]
        for w in self._workers: w.start()
    def submit(self, fn, priority=0):
        future = Future()
        with self._cond:
            self._counter += 1
            heapq.heappush(self._queue, (-priority, self._counter, fn, future))
            self._cond.notify()
        return future
    def _work(self):
        while True:
            with self._cond:
                while not self._queue and not self._shutdown:
                    self._cond.wait()
                if self._shutdown and not self._queue: return
                _, _, fn, future = heapq.heappop(self._queue)
            try: future.set_result(fn())
            except Exception as e: future.set_exception(e)
    def shutdown(self):
        with self._cond:
            self._shutdown = True
            self._cond.notify_all()
        for w in self._workers: w.join()

