def stream_json_array(file_path: str) -> Iterator[dict]:
    with open(file_path) as f:
        buf = ''
        depth = 0
        in_str = False
        started = False
        for char in iter(lambda: f.read(1), ''):
            if not started:
                if char == '[':
                    started = True
                continue
            if char == '"' and (not buf or buf[-1] != '\\'):
                in_str = not in_str
            if not in_str:
                if char == '{':
                    depth += 1
                elif char == '}':
                    depth -= 1
                    if depth == 0:
                        buf += char
                        yield json.loads(buf.strip())
                        buf = ''
                        continue
                elif char == ']' and depth == 0:
                    break
            if depth > 0:
                buf += char

