class WebScraper:
    def __init__(self, max_concurrent=5, cache_ttl=3600):
        self._sem = asyncio.Semaphore(max_concurrent)
        self._cache = {}
        self._ttl = cache_ttl
    async def scrape(self, url):
        if url in self._cache:
            val, ts = self._cache[url]
            if time.monotonic() - ts < self._ttl: return val
        async with self._sem:
            for attempt in range(3):
                try:
                    async with aiohttp.ClientSession() as s:
                        async with s.get(url, timeout=aiohttp.ClientTimeout(total=30)) as r:
                            result = {'url': url, 'status': r.status, 'content': (await r.text())[:5000]}
                            self._cache[url] = (result, time.monotonic())
                            return result
                except Exception as e:
                    if attempt == 2: return {'url': url, 'error': str(e)}
                    await asyncio.sleep(2 ** attempt)
    async def scrape_many(self, urls):
        return await asyncio.gather(*[self.scrape(u) for u in urls])

