        h = self._cmd_handlers.get(type(cmd))
        if not h: raise ValueError(f'No handler for {type(cmd).__name__}')
        return h.handle(cmd)
    def query(self, q):
        h = self._query_handlers.get(type(q))
        if not h: raise ValueError(f'No handler for {type(q).__name__}')
