class PluginManager:
    def __init__(self):
        self._plugins = {}
        self._order = []
    def register(self, plugin):
        for dep in plugin.dependencies:
            if dep not in self._plugins:
                raise RuntimeError(f'Missing dep: {dep}')
        self._plugins[plugin.name] = plugin
        self._order.append(plugin.name)
        plugin.on_load(self)
    def unregister(self, name):
        deps = [p.name for p in self._plugins.values() if name in p.dependencies]
        if deps: raise RuntimeError(f'{name} required by {deps}')
        p = self._plugins.pop(name, None)
        if p: p.on_unload(); self._order.remove(name)
    def get(self, name): return self._plugins.get(name)
    def emit(self, event, data=None):
        for n in self._order: self._plugins[n].on_event(event, data)

