class CronExpr:
    def __init__(self, expr):
        parts = expr.split()
        self.minute = self._parse(parts[0], 0, 59)
        self.hour = self._parse(parts[1], 0, 23)
        self.day = self._parse(parts[2], 1, 31)
        self.month = self._parse(parts[3], 1, 12)
        self.weekday = self._parse(parts[4], 0, 6)
    def _parse(self, f, lo, hi):
        if f == '*': return set(range(lo, hi+1))
        if '/' in f: return set(range(lo, hi+1, int(f.split('/')[1])))
        return {int(x) for x in f.split(',')}
    def matches(self, dt):
        return dt.minute in self.minute and dt.hour in self.hour and dt.day in self.day and dt.month in self.month and dt.weekday() in self.weekday

