        self._ensure_table()
    def _ensure_table(self):
        self._conn.execute('CREATE TABLE IF NOT EXISTS _migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)')
    def add_migration(self, version, up_fn, down_fn):
        self._migrations.append({'version': version, 'up': up_fn, 'down': down_fn})
