        row = self._conn.execute('SELECT version FROM _migrations ORDER BY applied_at DESC LIMIT 1').fetchone()
        return row[0] if row else None
    def get_applied(self):
        return {r[0] for r in self._conn.execute('SELECT version FROM _migrations').fetchall()}
    def migrate(self):
        applied = self.get_applied()
        for m in self._migrations:
            if m['version'] not in applied:
                m['up'](self._conn)
                self._conn.execute('INSERT INTO _migrations (version) VALUES (?)', (m['version'],))
                self._conn.commit()
    def rollback(self, steps=1):
        applied = sorted(self.get_applied(), reverse=True)
        for version in applied[:steps]:
            m = next((m for m in self._migrations if m['version'] == version), None)
            if m:
                m['down'](self._conn)
                self._conn.execute('DELETE FROM _migrations WHERE version = ?', (version,))
                self._conn.commit()

