    def add_transition(self, from_state, to_state, event, guard=None, action=None):
        self._transitions.append({'from': from_state, 'to': to_state, 'event': event, 'guard': guard, 'action': action})
    def send(self, event, context=None):
        for t in self._transitions:
            if t['from'] == self._state and t['event'] == event:
                if t['guard'] and not t['guard'](context):
                    continue
                if t['action']:
                    t['action'](context)
                self._state = t['to']
                self._history.append(self._state)
                return True
        return False
    def can_send(self, event, context=None):
        return any(t['from'] == self._state and t['event'] == event and (not t['guard'] or t['guard'](context)) for t in self._transitions)

class Reactive:
    def __init__(self, data: dict):
        self._data = dict(data)
        self._watchers = {}
        self._computeds = []
    def __getattr__(self, key):
        if key.startswith('_'): return super().__getattribute__(key)
        return self._data.get(key)
    def __setattr__(self, key, value):
        if key.startswith('_'): super().__setattr__(key, value); return
        old = self._data.get(key)
        self._data[key] = value
        if old != value:
            self._notify(key, old, value)
    def _notify(self, key, old, new):
        for cb in self._watchers.get(key, []):
            cb(new, old)
        for c in self._computeds:
            c._recompute(self)
    def watch(self, key, callback):
        self._watchers.setdefault(key, []).append(callback)

class Computed:
    def __init__(self, fn):
        self._fn = fn
        self._value = None
    def _recompute(self, reactive):
        self._value = self._fn(reactive)
    @property
    def value(self): return self._value

