class Schema:
    def __init__(self):
        self._types = {}
        self._resolvers = {}
    def add_type(self, name, fields):
        self._types[name] = fields
    def add_resolver(self, type_name, field, fn):
        self._resolvers.setdefault(type_name, {})[field] = fn
    def execute(self, query, context=None):
        parsed = self._parse(query)
        return self._resolve(parsed, 'Query', context)
    def _resolve(self, node, type_name, ctx, parent=None):
        result = {}
        for field_name, sub in node.items():
            args = sub.get('_args', {})
            resolver = self._resolvers.get(type_name, {}).get(field_name)
            if resolver:
                value = resolver(parent, args, ctx)
            else:
                value = parent.get(field_name) if parent else None
            if isinstance(value, dict) and sub.get('_fields'):
                result[field_name] = self._resolve(sub['_fields'], field_name, ctx, value)
            elif isinstance(value, list) and sub.get('_fields'):
                result[field_name] = [self._resolve(sub['_fields'], field_name, ctx, v) for v in value]
            else:
                result[field_name] = value
        return result
    def _parse(self, query):
        # Simplified parser
        return {'_raw': query}

