class Observer:
    def __init__(self, on_next=None, on_error=None, on_complete=None):
        self._next = on_next or (lambda x: None)
        self._error = on_error or (lambda e: None)
        self._complete = on_complete or (lambda: None)
    def next(self, value): self._next(value)
    def error(self, err): self._error(err)
    def complete(self): self._complete()

class Observable:
    def __init__(self, subscribe_fn):
        self._subscribe_fn = subscribe_fn
    def subscribe(self, observer=None, on_next=None, on_error=None, on_complete=None):
        if observer is None:
            observer = Observer(on_next, on_error, on_complete)
        self._subscribe_fn(observer)
    def pipe(self, *operators):
        result = self
        for op in operators:
            result = op(result)
        return result
    @staticmethod
    def from_iterable(data):
        def subscribe(observer):
            try:
                for item in data:
                    observer.next(item)
                observer.complete()
            except Exception as e:
                observer.error(e)
        return Observable(subscribe)

def map_op(fn):
    def operator(source):
        def subscribe(observer):
            source.subscribe(Observer(lambda x: observer.next(fn(x)), observer.error, observer.complete))
        return Observable(subscribe)
    return operator

def filter_op(fn):
    def operator(source):
        def subscribe(observer):
            source.subscribe(Observer(lambda x: observer.next(x) if fn(x) else None, observer.error, observer.complete))
        return Observable(subscribe)
    return operator

def take(n):
    def operator(source):
        def subscribe(observer):
            count = [0]
            def on_next(x):
                if count[0] < n:
                    observer.next(x)
                    count[0] += 1
                    if count[0] >= n: observer.complete()
            source.subscribe(Observer(on_next, observer.error, observer.complete))
        return Observable(subscribe)
    return operator

