class SagaStep:
    def __init__(self, name, execute, compensate):
        self.name = name
        self.execute = execute
        self.compensate = compensate

class SagaResult:
    def __init__(self, success, results=None, error=None, failed_step=None):
        self.success = success
        self.results = results or {}
        self.error = error
        self.failed_step = failed_step

class Saga:
    def __init__(self):
        self._steps = []
    def step(self, name, execute_fn, compensate_fn):
        self._steps.append(SagaStep(name, execute_fn, compensate_fn))
        return self
    async def run(self, context=None):
        results = {}
        completed = []
        for step in self._steps:
            try:
                r = step.execute(context, results)
                if asyncio.iscoroutine(r): r = await r
                results[step.name] = r
                completed.append(step)
            except Exception as e:
                for s in reversed(completed):
                    try:
                        c = s.compensate(context, results)
                        if asyncio.iscoroutine(c): await c
                    except Exception: pass
                return SagaResult(False, results, e, step.name)
        return SagaResult(True, results)

