class Stage:
    def __init__(self, name, fn, concurrency=1, buffer_size=100):
        self.name = name
        self.fn = fn
        self.concurrency = concurrency
        self.queue = asyncio.Queue(maxsize=buffer_size)
        self.output = asyncio.Queue(maxsize=buffer_size)

class Pipeline:
    def __init__(self):
        self._stages = []
    def stage(self, name, fn, concurrency=1):
        self._stages.append(Stage(name, fn, concurrency))
        return self
    async def run(self, input_data):
        if not self._stages: return list(input_data)
        results = []
        errors = []
        # Feed input
        first = self._stages[0]
        for item in input_data:
            await first.queue.put(item)
        await first.queue.put(None)  # sentinel
        # Process stages
        for i, stage in enumerate(self._stages):
            workers = []
            next_q = self._stages[i+1].queue if i+1 < len(self._stages) else None
            for _ in range(stage.concurrency):
                workers.append(asyncio.create_task(self._worker(stage, next_q, results, errors)))
            await asyncio.gather(*workers)
            if next_q:
                await next_q.put(None)
        return results
    async def _worker(self, stage, next_q, results, errors):
        while True:
            item = await stage.queue.get()
            if item is None:
                await stage.queue.put(None)
                break
            try:
                r = stage.fn(item)
                if asyncio.iscoroutine(r): r = await r
                if next_q: await next_q.put(r)
                else: results.append(r)
            except Exception as e:
                errors.append((stage.name, item, e))

