from typing import get_type_hints, Any

class Container:
    def __init__(self):
        self._registry = {}
        self._singletons = {}
        self._scoped = {}
    def register(self, interface, impl=None, lifetime='transient'):
        impl = impl or interface
        self._registry[interface] = {'impl': impl, 'lifetime': lifetime}
    def resolve(self, interface):
        entry = self._registry.get(interface)
        if not entry: raise KeyError(f'{interface} not registered')
        if entry['lifetime'] == 'singleton':
            if interface not in self._singletons:
                self._singletons[interface] = self._create(entry['impl'])
            return self._singletons[interface]
        if entry['lifetime'] == 'scoped':
            if interface not in self._scoped:
                self._scoped[interface] = self._create(entry['impl'])
            return self._scoped[interface]
        return self._create(entry['impl'])
    def _create(self, impl):
        hints = get_type_hints(impl.__init__) if hasattr(impl, '__init__') else {}
        params = inspect.signature(impl).parameters
        args = {}
        for name, param in params.items():
            if name == 'self': continue
            hint = hints.get(name)
            if hint and hint in self._registry:
                args[name] = self.resolve(hint)
        return impl(**args)
    def create_scope(self):
        scope = Container()
        scope._registry = dict(self._registry)
        scope._singletons = self._singletons
        return scope
